using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Reflection;
using System.Collections.Generic;
using System.Text.RegularExpressions;
internal sealed class CompanionUpdateInfo {internal Version Version;internal string Download;}
internal static class CompanionUpdates {
 internal const string Releases="https://api.github.com/repos/Chaavesss/Mon-Espace/releases?per_page=50";
 internal static readonly Version Current=Assembly.GetExecutingAssembly().GetName().Version;
 internal static CompanionUpdateInfo Parse(string json){var releases=Store.Json.Deserialize<List<Dictionary<string,object>>>(json);CompanionUpdateInfo newest=null;if(releases==null)return null;foreach(var release in releases){object tag,draft,pre;if(!release.TryGetValue("tag_name",out tag)||release.TryGetValue("draft",out draft)&&Equals(draft,true)||release.TryGetValue("prerelease",out pre)&&Equals(pre,true))continue;var match=Regex.Match(tag as string??"",@"^compagnon-dofus-v([0-9]+\.[0-9]+\.[0-9]+)$");Version parsed;if(!match.Success||!Version.TryParse(match.Groups[1].Value+".0",out parsed)||parsed<=Current)continue;string download="https://github.com/Chaavesss/Mon-Espace/releases/tag/"+(string)tag;object assets;if(release.TryGetValue("assets",out assets)){var list=assets as object[];if(list==null){var array=assets as System.Collections.ArrayList;if(array!=null)list=array.ToArray();}if(list!=null)foreach(var value in list){var asset=value as Dictionary<string,object>;object name,url;if(asset!=null&&asset.TryGetValue("name",out name)&&Equals(name,"CompagnonDofus.zip")&&asset.TryGetValue("browser_download_url",out url)){string expected="https://github.com/Chaavesss/Mon-Espace/releases/download/"+(string)tag+"/CompagnonDofus.zip";if(Equals(url,expected))download=expected;}}}if(newest==null||parsed>newest.Version)newest=new CompanionUpdateInfo{Version=parsed,Download=download};}return newest;}
 internal static async System.Threading.Tasks.Task<CompanionUpdateInfo> Check(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;using(var http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(12)}){http.DefaultRequestHeaders.UserAgent.ParseAdd("CompagnonDofus/"+Current);using(var response=await http.GetAsync(Releases,HttpCompletionOption.ResponseHeadersRead)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>2*1024*1024)throw new IOException("Réponse de mise à jour trop volumineuse.");using(var stream=await response.Content.ReadAsStreamAsync())using(var buffer=new MemoryStream()){var bytes=new byte[8192];int count;while((count=await stream.ReadAsync(bytes,0,bytes.Length))>0){if(buffer.Length+count>2*1024*1024)throw new IOException("Réponse de mise à jour trop volumineuse.");buffer.Write(bytes,0,count);}return Parse(System.Text.Encoding.UTF8.GetString(buffer.ToArray()));}}}}
 internal static void Test(){string json=@"[{""tag_name"":""v99.0.0"",""assets"":[]},{""tag_name"":""compagnon-dofus-v98.0.0"",""draft"":true},{""tag_name"":""compagnon-dofus-v97.0.0"",""prerelease"":true},{""tag_name"":""compagnon-dofus-v96.0.0"",""assets"":[{""name"":""CompagnonDofus.zip"",""browser_download_url"":""https://evil.example/file.zip""}]}]";var result=Parse(json);if(result==null||result.Version.Major!=96||result.Download!="https://github.com/Chaavesss/Mon-Espace/releases/tag/compagnon-dofus-v96.0.0")throw new Exception("Filtrage des mises à jour");if(Parse(@"[{""tag_name"":""compagnon-dofus-v0.1.0""}]")!=null)throw new Exception("Ancienne version proposée");}
}
internal sealed partial class CompanionWindow {
 bool checkingUpdates,updatesChecked;string updateMessage="Vérification au lancement",updateUrl="",updateVersion="";System.Windows.Controls.TextBlock updateStatus;System.Windows.Controls.Button updateDownload,updateCheck;
 System.Windows.Controls.Panel BuildUpdatePanel(){var panel=new System.Windows.Controls.StackPanel{Margin=new System.Windows.Thickness(0,6,0,0)};updateStatus=Text(updateMessage,10,true);panel.Children.Add(updateStatus);var tools=new System.Windows.Controls.WrapPanel();updateCheck=Button("Vérifier les mises à jour",()=>CheckForUpdates(true));tools.Children.Add(updateCheck);updateDownload=Button("Télécharger la mise à jour",DownloadUpdate);tools.Children.Add(updateDownload);panel.Children.Add(tools);UpdateNotice();return panel;}
 void UpdateNotice(){if(updateStatus!=null)updateStatus.Text=updateMessage;if(updateCheck!=null)updateCheck.IsEnabled=!checkingUpdates&&!downloadingUpdate;if(updateDownload!=null)updateDownload.IsEnabled=!downloadingUpdate;if(updateDownload!=null)updateDownload.Visibility=String.IsNullOrEmpty(updateUrl)?System.Windows.Visibility.Collapsed:System.Windows.Visibility.Visible;}
 async void CheckForUpdates(bool force=false){if(testing||checkingUpdates||updatesChecked&&!force)return;updatesChecked=true;checkingUpdates=true;updateMessage="Recherche d’une mise à jour du compagnon…";UpdateNotice();try{var result=await CompanionUpdates.Check();if(result==null){updateUrl="";updateMessage="Compagnon "+CompanionUpdates.Current.ToString(3)+" · à jour";}else{updateUrl=result.Download;updateVersion=result.Version.ToString(3);updateMessage="Nouvelle version "+updateVersion+" disponible · téléchargez-la ici";}}catch{updateMessage="Vérification indisponible · réessayez quand vous êtes connecté.";}finally{checkingUpdates=false;UpdateNotice();if(!closing)RefreshView();}}
}

